from sympy import isprime

def prime_fib(n: int) -> int:
    def fib_generator():
        a, b = 0, 1
        while True:
            a, b = b, a + b
            yield a

    fib_iter = fib_generator()
    prime_fibs = [next(fib_iter) for _ in range(n)]
    while not isprime(prime_fibs[-1]):
        prime_fibs.append(next(fib_iter))
    return prime_fibs[-1]

from sympy import primerange

def is_multiply_prime(a):
    """Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    for i in primerange(2, 100):
        if a % i == 0:
            count = 1
            for j in primerange(2, 100):
                if j != i and a % (i * j) == 0:
                    count += 1
                    if count > 3:
                        return False
            if count == 3:
                return True
    return False

